entries[235230] = { ["name"] = "Wirkungsloser Trank", ["text"] = "Benutzen: Trinkt, um Euren Durst zu stillen und Eure Lässigkeit zu beweisen.\n\nWenn Ihr in Lorenhall 10 Sek. lang mit Trinken verbringt, werdet Ihr ' Gut hydriert ', was Eure Bewegungsgeschwindigkeit 1 Stunde lang um 10% erhöht. (5 Min Abklingzeit)\n\"Die ganze Klasse eines alkoholischen Getränks, nur ohne Alkohol!\"\nVerkaufspreis:" }
entries[235238] = { ["name"] = "Explodierter Zünder", ["text"] = "Benutzen: Stellt einen explodierten Zünder auf. Ihr könnt mit aller Kraft auf den Zünder drücken und an ihm ziehen, um Interessierten zu demonstrieren, wie viel Kraft Ihr habt.\n\nWenn Ihr ihn in Lorenhall benutzt, wird Eure Stärke 8% imposanter. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[235255] = { ["name"] = "Solider Würfel", ["text"] = "Benutzen: Würfelt 2 6-Seiten-Würfel und hofft auf das Beste!\n\nBeim Würfeln in Lorenhall wird Eure Beweglichkeit um X% erhöht, wobei X die Summe Eures Würfelwurfs ist. Wenn Ihr Schlangenaugen würfelt, kann das ein schreckliches Schicksal nach sich ziehen. (5 Min Abklingzeit)\nVerkaufspreis:" }
