entries[235359] = { ["name"] = "Rattenzahngift", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure schädlichen Zauber und Fähigkeiten belegen Euer Ziel mit 'Rattenzahngift'. Bis zu 5-mal stapelbar.\nBenutzen: Setzt alle Giftstapel frei, um ( 664998 * 1 ) Naturschaden sowie pro Stapel im Verlauf von 5 Sek. ( 76000 * 1 ) Naturschaden zu verursachen. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[235363] = { ["name"] = "Verdächtiger Energietrank", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Wenn Ihr schädliche Zauber oder Fähigkeiten einsetzt, besteht eine Chance, dass Ihr auch einen Schluck des Energietranks nehmt, wodurch sich Eure Meisterschaft 10 Sek. lang um 2678 erhöht. Gewährt 393 zusätzliche Meisterschaft, wenn Ihr Eure Gesundheit unter 35% liegt.\n\"Ein todesverachtendes Gebräu nach Mamas Geheimrezept, das Euren Selbsterhaltungssinn betäubt.\"\nVerkaufspreis:" }
