entries[235373] = { ["name"] = "Abgründiges Volt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 Intelligenz\nBenutzen: Superladet Euch selbst und erhöht 15 Sek. lang Euer Tempo um 4767 . Der erste Verbündete, den Ihr heilt, wird auch aufgeladen, was sein Tempo 10 Sek. lang um 1422 erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[235378] = { ["name"] = "Landros Beutekiste", ["text"] = "Wird beim Aufheben gebunden\n\"WARNUNG: Ohne Gewähr. Enthält möglicherweise kein tatsächliches Reittier.\"" }
entries[235384] = { ["name"] = "Animasauger", ["text"] = "Questgegenstand\nBenutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\nKann beim Zaubern laufen. (3 Sek. Abklingzeit)\n\"Hat ein Portal auf der Rückseite der Waffe. Früher führte es nach K'aresh, aber wer weiß schon, wohin jetzt? Zumindest nicht hierher.\"" }
entries[235388] = { ["name"] = "Farbe: Tiefrot", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kauft diese Farbe, um dauerhaft diese Farbpalette für Euren 99-G-Genickbrecher freizuschalten.\nErfordert einen ehrfürchtigen Ruf beim Bilgewasserkartell in Lorenhall und dass Ihr diese Farbe noch nicht kennt.\n\"Rot ist natürlich die schnellste Farbe.\"" }
