entries[235390] = { ["name"] = "Farbe: Taumel-Blau", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kauft diese Farbe, um dauerhaft diese Farbpalette für Euren 99-G-Genickbrecher freizuschalten.\nErfordert einen ehrfürchtigen Ruf bei der Schwarzmeer AG in Lorenhall und dass Ihr diese Farbe noch nicht kennt.\n\"Warnung: Vom Deaktivieren der Stabilitätskontrolle beim Fahren in Taumel-Blau wird abgeraten.\"" }
entries[235391] = { ["name"] = "Farbe: Gelbes Kuchengelb", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kauft diese Farbe, um dauerhaft diese Farbpalette für Euren 99-G-Genickbrecher freizuschalten.\nErfordert einen ehrfürchtigen Ruf bei der Venture Company in Lorenhall.\nErfordert einen ehrfürchtigen Ruf bei der Venture Company in Lorenhall und dass Ihr diese Farbe noch nicht kennt.\n\"Eine leckere Farbe ohne Nebenwirkungen.\"" }
