entries[235499] = { ["name"] = "Reshiiwickel", ["text"] = "Wird beim Aufheben gebunden\nRücken\n70 Rüstung\n+66 [Beweglichkeit oder Stärke oder Intelligenz]\n+100 Ausdauer\n\nFasersockel\nAnlegen: [Die Wickel stimmen sich auf Eure Spezialisierung ein und gewähren Euch ' Astrale Rekonstitution ':\n\nEure hilfreichen Zauber und Fähigkeiten haben eine Chance, schlummernde Energien zu sammeln, um einen Verbündeten um 6130 Gesundheit zu heilen. Überschüssige Heilung aus diesem Effekt gewährt 20 Sek. lang einen Absorptionsschild. ][Die Wickel stimmen sich auf Eure Spezialisierung ein und gewähren Euch ' Astraler Schutz ':\n\nEure Zauber und Fähigkeiten haben eine hohe Chance, die Euch umgebende Energie zu verschmelzen, um Euch einen Schild zu gewähren, der den erlittenen Schaden um 20% bis zu höchstens 9535 verringert.\n\nWenn Eure Gesundheit unter 40% sinkt, erhaltet Ihr diesen Effekt mit einer Effektivität von 500%. Dieser Effekt kann nur einmal alle 6 Min. auftreten. ][Die Wickel stimmen sich auf Eure Spezialisierung ein und gewähren Euch ' Astrales Schröpfen ':\n\nEure schädlichen Zauber und Fähigkeiten haben eine Chance, latente Energien aus Eurer Umgebung zu fokussieren, um 4768 Arkanschaden zu verursachen, der zwischen Eurem Ziel und Gegnern in der Nähe aufgeteilt wird. Gegner mit weniger als 35% Gesundheit erleiden 20% zusätzlichen Schaden. ]\nVerkaufspreis:" }
entries[235500] = { ["name"] = "Einlullender Pfeil", ["text"] = "Questgegenstand\nBenutzen: Verschießt einen Betäubungspfeil auf Euer Ziel, der es in seligen Tiefschlaf versetzt.\n\"Betäubt alles, das er trifft, indem er vorübergehend das spirituelle Netz unterbricht. Nicht-invasiv und schmerzfrei. Offenbar ein üblicher Streich, den man ahnungslosen Freunden spielt.\"" }
entries[235501] = { ["name"] = "Nekrorochenschleim", ["text"] = "Questgegenstand\n\"Abgekratzt vom Rücken eines Nekrorochens. Es ist eine sehr zähflüssige, klebrige Substanz. Das in ein Gefäß zu bekommen, ist eine Tortur.\"" }
