entries[235515] = { ["name"] = "Janis Müllhaufen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Für die einen isses Müll, für die anderen 'n Loa! Harharhar...\"\nErfolg:\nDie Waffen nieder\nKategorie:\nErweiterungsfeatures" }
entries[235516] = { ["name"] = "Das Abfindungspaket", ["text"] = "Kosmetisch\nWird beim Aufheben gebunden\nDistanz Schusswaffe\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[235519] = { ["name"] = "Anhänger der geachteten Legende", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Repräsentiert Euren Saisonerfolg mit einem Banner. (2 Min Abklingzeit)" }
entries[235523] = { ["name"] = "Stabiler Holzstuhl", ["text"] = "1\nBehausungsdekoration\nWird an Kriegsmeute gebunden\nBenutzen: Diese Dekoration wird beim Kauf sofort Eurer Haustruhe hinzugefügt.\nVerkaufspreis:" }
entries[235531] = { ["name"] = "Restaurierter Kastenschlüssel", ["text"] = "Saison 2 von The War Within\nWird beim Aufheben gebunden\nEinzigartig\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 2 freigeschaltet.\nVerkaufspreis:" }
entries[235532] = { ["name"] = "Experimenteller Goblin-Treibstoffzuschlag", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Verringert die maximale Gesundheit um 50% und verleiht einen zufälligen Kampfbonus.\n\nKann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist. (5 Min Abklingzeit)\n\"Verfallsdatum: 'Seid Ihr etwa ein Drückeberger?'\"" }
entries[235533] = { ["name"] = "Autobewerberprototyp", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Platziert den Autobewerber, der alle Kreaturen in der Nähe extrem anwidert, wodurch sie Euch 3 Min. lang 50% mehr Schaden zufügen.\n\nKann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist. (5 Min Abklingzeit)\n3 Aufladungen\nErfordert einen freundlichen Ruf beim Kartell der Düsternisverschmolzenen in Lorenhall.\n\"Wird mit einer minimalen Anzahl von Werbung geliefert. Macht EURE persönliche Marke stilvoll bekannt!\"" }
entries[235534] = { ["name"] = "Elektropunkturtestmodell", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Das Ziel wird von belebender Spannung durchströmt, was 3 Min. lang sein Tempo um 20% erhöht, den erlittenen Schaden um 25% verringert und es Naturschaden pulsieren lässt.\n\nKann bei den meisten seltenen Kreaturen in Lorenhall eingesetzt werden. Ziele lassen zusätzliche Marktforschung für alle Spielercharaktere fallen, während dieser Effekt aktiv ist. (10 Min Abklingzeit)\n3 Aufladungen\nErfordert einen wohlwollenden Ruf beim Kartell der Düsternisverschmolzenen in Lorenhall.\n\"Ihr wollt mehr Stress und Anspannung in Eurem Leben? Gesucht, gefunden!\"" }
entries[235535] = { ["name"] = "Diskret verpackte Erfindung", ["text"] = "Wird an Kriegsmeute gebunden\n\"Die besten Lösungen sind Düsternisverschmolzene Lösungen. Moment, das ist ein echt fescher Slogan! Gleich aufschreiben!\"" }
entries[235546] = { ["name"] = "Zerfledderte Tagebuchseite", ["text"] = "Questgegenstand\n\"Die Seite ist kaum leserlich und stark verwittert. Das Tagebuch scheint lange den Elementen ausgesetzt gewesen zu sein.\"" }
entries[235548] = { ["name"] = "Vorrat der irdenen Landratte", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält ein Ausrüstungsstück des Champions.\"\n<Zum Öffnen rechtsklicken>" }
entries[235549] = { ["name"] = "Karmesinroter Schredderpanzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Experimenteller Schredder, der mehr zum Töten und weniger zum Holzfällen entworfen wurde.\"\nErfolg:\nSchlüsselsteinmeister von The War Within: Saison 2\nKategorie:\nDungeons" }
entries[235554] = { ["name"] = "Mitternachtschwarzes Dunkelmondstreitross", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer mitternachtschwarzes Dunkelmondstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\nHandelsposten" }
entries[235555] = { ["name"] = "Lebhaftes Dunkelmondstreitross", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer lebhaftes Dunkelmondstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In zerfledderte Zirkusbanner gehüllt, ist dieses schauerliche Reittier die perfekte Mischung aus Schatten und Spektakel.\"\nHandelsposten" }
entries[235556] = { ["name"] = "Violettes Dunkelmondstreitross", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euer violettes Dunkelmondstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses Ross trägt die Rätselhaftigkeit und Magie des Dunkelmondjahrmarkts in sich.\"\nHandelsposten" }
