entries[235623] = { ["name"] = "Rubinschuppentreter", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nFüße Kosmetisch\n\"Schlagt die Hacken Eurer Treter aneinander, aber nicht zu doll.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[235624] = { ["name"] = "Saphirschuppentreter", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nFüße Kosmetisch\n\"Saphire sind für ihren Härtegrad bekannt. Ein Tritt mit diesen Tretern tut höllisch weh.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[235626] = { ["name"] = "Schlüssel zu Chef G", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört Gallytron oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sieht nicht so aus, als wäre unter der Haube irgendetwas Besonderes, aber wartet nur, bis die Goblins nebenan Euch bei der nächsten Poolparty vorfahren sehen.\"\nBeute:\nChromkönig Gallywix\nZone:\nBefreiung von Lorenhall (Mythisch)" }
entries[235627] = { ["name"] = "Krickelkrakels Lieblingsnaschereien", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Sorgt dafür, dass Krickelkrakel stets bereit ist, Eure Berufsspezialisierung zurückzusetzen.\"" }
entries[235628] = { ["name"] = "Beute des Tiefenforschers", ["text"] = "80 ( 80)\n\"Truhen der großzügigen Tiefe können Beute des Tiefenforschers enthalten. Diese seltene Karte führt Euch zu einem versteckten Schatz, der mächtige Ausrüstung, zusätzliche Währungen und eine neue oder aufgewertete Kuriosität enthält. Einmal wöchtentlich pro Charakter verfügbar.\"" }
