entries[235700] = { ["name"] = "Zügel des leerenvernarbten Greifs", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen leerenvernarbten Greif beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von seinen Haltern verlassen, suchte der leerenvernarbte Greif nach allerlei übrigen Nahrungsquellen, von denen die meisten jedoch von der Leere verdorben waren. Jetzt, wo sie von der Leere genährt werden, landen sie nur, wenn ihr wankelmütiger Appetit von Nahrung angeregt wird, an die sie sich wohlwollend erinnern.\"\nBeute:\nLeerenvernarbter Greif\nZone:\nVision von Sturmwind (Neuerlebt)" }
entries[235701] = { ["name"] = "Zerfallendes Konstruktionsset für einen Mechaverschrotter", ["text"] = "Dauer: 1 tag (Realzeit)\nBenutzen: Erstellt einen mechanischen Schrottbot, der Ausrüstung repariert und fast alles kauft. Nach 5 Min. verschwindet er. (15 Min Abklingzeit)\n\"Aufgrund ihrer unsachgemäßen Verpackung verlieren die Komponenten dieses Sets laufend an Energie.\"\nVerkaufspreis:" }
entries[235703] = { ["name"] = "Noggenfoggers Zwergenauslese", ["text"] = "Benutzen: Werdet etwas kleiner. Bis zu 10-mal stapelbar.\n\"Garantiertes Schrumpfen! Jetzt auf ex trinkbar!\"\nVerkaufspreis:" }
entries[235704] = { ["name"] = "Noggenfoggers Riesenauslese", ["text"] = "Benutzen: Werdet etwas größer. Bis zu 10-mal stapelbar.\n\"Seid Ihr es leid, von oben herab behandelt zu werden? Jetzt auf ex trinkbar!\"\nVerkaufspreis:" }
entries[235705] = { ["name"] = "Zügel des leerenvernarbten Hengstes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Geschmiedet wie einst die Eisen an ihren Hufen, handelt es sich bei diesen Kreaturen nun weniger um Pferde sondern mehr um Leerenenergie in ihrer Gestalt.\"\nBeute:\nLeerengeschmiedeter Hengst\nZone:\nVision von Sturmwind (Neuerlebt)" }
entries[235706] = { ["name"] = "Harnisch der leerenvernarbten Rudelmutter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Im Kampf gegen ihre verdorbenen Halter konnte diese Rudelmutter sich und ihre Welpen befreien. Doch Freiheit von ihren Haltern bedeutete noch lange keine Freiheit von der Leere dieses verlorenen Ortes. Sie brachte ihren Welpen bei, zu noch gefährlicheren Bestien zu werden. Nun durchstreifen sie Orgrimmar auf der Suche nach Futter, während alle ums Überleben kämpfen.\"\nBeute:\nLeerenvernarbte Rudelmutter\nZone:\nVision von Orgrimmar (Neuerlebt)" }
entries[235707] = { ["name"] = "Zügel des leerenvernarbten Windreiters", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen leerenvernarbten Windreiter beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als die Leerenenergien entfesselt wurden, verfielen die meisten Windreiter in Raserei, wobei sie sich gegenseitig und ihre Ausbilder töteten. Die Tore zu ihrem Horst wurden von den Überlebenden verschlossen. Oben kann man noch einige der überlebenden Windreiter gleiten sehen, doch niemand traut sich, in ihr neues, tödliches Zuhause zurückzukehren, um zu sehen, was davon übrig ist.\"\nBeute:\nLeerenvernarbter Windreiter\nZone:\nVision von Orgrimmar (Neuerlebt)" }
entries[235709] = { ["name"] = "Ny'alothischer Schattenwurm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört Euren ny'alothischen Schattenwurm oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Als Überrest der Vergangenheit des Schwarzen Imperiums kehren diese Vorläufer der Kluftwürmer mit dem Aufstieg von Ny'alotha wieder zurück.\"\nErfolg:\nMeister der VisionenKategorie:\nNeuerlebte Visionen von N'Zoth" }
entries[235710] = { ["name"] = "Noggenfoggers Frischeauslese", ["text"] = "Wird beim Aufheben gebunden\nVölker: Goblin\nBenutzen: Wird vorübergehend kalt.\n\"Tragt die neueste Mode, esst in den schicksten Restaurants und trinkt die angesagtesten Tränke!\"\nVerkaufspreis:" }
entries[235711] = { ["name"] = "Verderbnis der Aspekte", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört die Verderbnis der Aspekte oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert den Erfolg \"Gemeinsame Erinnerungen\", bei dem alle Aufwertungen für das Stundenglas der verstörenden Visionen freigeschaltet werden müssen.\n\n\"Mit N'Zoths Triumph wird das, was mit Galakrond begann, endlich Wirklichkeit. Und mit dem Verschwinden der Aspekte ist das Verderben ihrer Spezies vollbracht.\"\nVerkäufer:\nTorie\nZone:\nDornogal\nKosten:\n40.000" }
entries[235712] = { ["name"] = "Leerenkristallpanther", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\nBeschwört einen reitbaren Leerenkristallpanther oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Obwohl viele kostbare Edelsteine in verstörenden Visionen von den Leerenenergien verderbt wurden, können Juwelierskunstmeister sie immer noch verwenden, um mächtige Pantherrösser herzustellen.\"\nBeruf:\nJuwelierskunst" }
entries[235713] = { ["name"] = "Seltsamer Sand", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Esst mich.\n\"Bodensatz von Noggenfoggers Auslese. Muss Teil des Rezepts sein.\"" }
entries[235715] = { ["name"] = "Blauer Floristern", ["text"] = "Questgegenstand\n\"Umgeben von samtigen Blüten riecht der sternenförmige Kern nach Zitrone und einer sanften Meeresbrise.\"" }
entries[235716] = { ["name"] = "Ensemble: Umhang des ewigen Potenzials", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die exklusiven Vorlagen des Umhangs des ewigen Potenzials.\n\"Enthält exklusive Vorlagen des Umhangs des ewigen Potenzials.\"" }
