entries[235799] = { ["name"] = "Wurfsägeblatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Wirft das Sägeblatt einem freundlich gesinnten Spielercharakter zu. Wenn möglich, wird er sie automatisch zurückwerfen! (5 Sek. Abklingzeit)\nErfordert einen respektvollen Ruf bei der Venture Company in Lorenhall.\n\"Hoffentlich fangt Ihr es auch.\"" }
entries[235800] = { ["name"] = "Rezept: Authentische Muschelsuppe à la Lorenhall", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die richtige Zubereitung der Muschelsuppe à la Lorenhall.\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:" }
entries[235801] = { ["name"] = "Persönlicher Fischkutter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ihr könnt Euch über Wasser fortbewegen.\nErfordert einen respektvollen Ruf bei der Schwarzmeer AG in Lorenhall.\n\"Achtung: Bei Wasserkontakt erlischt die Garantie.\"" }
entries[235803] = { ["name"] = "Trank der mysteriösen Schnelligkeit", ["text"] = "Nach dem Plündern: Erhöht Eure Bewegungsgeschwindigkeit um 10%.\n\nHält 30 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht." }
entries[235805] = { ["name"] = "Authentische Muschelsuppe à la Lorenhall", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 1350000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und Euer höchster Sekundärwert wird 1 Stunde lang um 470 erhöht.\n\"Die einzig Wahre. Das Original. Absolute Granate. Die perfekte Muschelsuppe!\"\nVerkaufspreis:" }
entries[235807] = { ["name"] = "Laden-aus-der-Kiste", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Platziert einen Goblinmarktstand, der 15 Min. lang stehen bleibt. Kann nur im Freien eingesetzt werden. (15 Min Abklingzeit)\nErfordert einen respektvollen Ruf beim Bilgewasserkartell in Lorenhall.\n\"Man sollte immer bereit sein, einen Laden zu eröffnen.\"" }
