entries[236407] = { ["name"] = "Leerenfluchedelstein", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"Ein begehrter Gegenstand, der regelmäßig für illegale Aktivitäten verwendet wird.\"" }
