entries[236412] = { ["name"] = "\"Feuerfester\" Wumms", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erlebt Leuchtendo aus nächster Nähe mit diesem starken Feuerschutztrank! Verringert erlittenen Feuerschaden um 5% und erhöht erlittenen Naturschaden um 25%.\n\nNur während des Kampfes im Kessel des Gemetzels verwendbar. (1 Min Abklingzeit)\n\"Typische Nebenwirkungen sind Gänsehaut, Zittern und leichte Übelkeit.\"\nVerkaufspreis:" }
entries[236413] = { ["name"] = "\"Schockfeste\" Limo", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kommt Torq mit diesem mächtigen Schockschutztrank nahe genug, um ihn zu berühren! Verringert erlittenen Naturschaden um 5% und erhöht erlittenen Feuerschaden um 25%.\n\nNur während des Kampfes im Kessel des Gemetzels verwendbar. (1 Min Abklingzeit)\n\"Typische Nebenwirkungen sind Hitzewallungen, Schweißausbrüche und leichte Übelkeit.\"\nVerkaufspreis:" }
entries[236415] = { ["name"] = "Zügel der gefleckten schwarzen Reitziege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare gefleckte schwarze Reitziege und gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Einmal kam ein Landarbeiter vorbei, ohne diesen Widder zu streicheln. Mehr brauchte die Ziege nicht, um daraus eine persönliche Angelegenheit zu machen.\"\nHandelsposten" }
