entries[236753] = { ["name"] = "Xy'vox' Zufluchtdämpfer", ["text"] = "Dieser Gegenstand startet eine Quest.\n\"Xy'vox ist extrem gefährlich und sollte nicht allein bekämpft werden.\"" }
entries[236756] = { ["name"] = "Sozialverträgliche Trinkgeldtruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Tapferkeitssteine, Wappen, Resonanzkristalle und Gold.\"\n<Zum Öffnen rechtsklicken>" }
entries[236757] = { ["name"] = "Großzügige Trinkgeldtruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Tapferkeitssteine, Wappen, Resonanzkristalle und Gold.\"\n<Zum Öffnen rechtsklicken>" }
entries[236758] = { ["name"] = "Extravagante Trinkgeldtruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Tapferkeitssteine, Wappen, Resonanzkristalle und Gold.\"\n<Zum Öffnen rechtsklicken>" }
entries[236762] = { ["name"] = "Tazaveshfassade", ["text"] = "Questgegenstand\n\"Der perfekte Gegenstand, um sich unter die kriminellen Elemente Tazaveshs zu mischen.\"" }
entries[236763] = { ["name"] = "Finderlohn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schwarzmeer AG\n- Freundlich\nErfordert eine abgeschlossene C.H.E.T.T.-Liste.\n\"Eine kleine Summe für geschmuggelte Waren und eine gute Empfehlung für Eure Kriegsmeute.\"" }
entries[236764] = { ["name"] = "Finderlohn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Bilgewasserkartell\n- Freundlich\nErfordert eine abgeschlossene C.H.E.T.T.-Liste.\n\"Eine kleine Summe für geschmuggelte Waren und eine gute Empfehlung für Eure Kriegsmeute.\"" }
entries[236765] = { ["name"] = "Finderlohn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Venture Company\n- Freundlich\nErfordert einen ehrfürchtigen Ruf bei der Venture Company in Lorenhall und dass Ihr diese Farbe noch nicht kennt.\nErfordert eine abgeschlossene C.H.E.T.T.-Liste.\n\"Eine kleine Summe für geschmuggelte Waren und eine gute Empfehlung für Eure Kriegsmeute.\"" }
entries[236766] = { ["name"] = "Essenzscanner", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Prüft auf Schattenwachen in einem nahen Umkreis." }
entries[236768] = { ["name"] = "Krabbumm", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[236769] = { ["name"] = "Leitungsverleger des Garbagio", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verlegt die Wasserleitungen des Garbagio-Brunnens ohne ersichtlichen Grund 2 Min. lang zu Eurer Position. (10 Min Abklingzeit)\n\"Die massiven industriellen Abwässer von Lorenhall sorgen dafür, dass die Kosten von Farbstoffen niedrig bleiben! Achtung! Jeglichen Hautkontakt vermeiden.\"" }
entries[236772] = { ["name"] = "Strom'kar der Kriegsbrecher", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigt Waffenkrieger\n\"Der letzte Schlag wird durch den Stahl des barbarischen Königs erfolgen. Mit ihm wird das Getöse der Schlacht verstummen und für das erste Königreich wird ein neues Zeitalter des Friedens beginnen.\"" }
entries[236773] = { ["name"] = "Verschlucktes Kaja'mit", ["text"] = "Questgegenstand\n\"Auf die schlimmste Weise schleimig.\"" }
entries[236781] = { ["name"] = "Weggeworfenes Schattenschriftstück", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"Eine weggeworfene, verschlüsselte Nachricht.\"" }
entries[236783] = { ["name"] = "Astralsiegel", ["text"] = "Questgegenstand\n\"Erhaltet ungefragten Zugang zu unerwähnten Orten.\"" }
entries[236785] = { ["name"] = "C.H.E.T.T.-Karte", ["text"] = "Questgegenstand\n\"Nachweis der Mitgliedschaft bei C.H.E.T.T.-Services.\"" }
