entries[236852] = { ["name"] = "Überfliegerkawummstein des Garbagio", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erfüllt Eure Rüstung mit einem schwachen Echo der Macht des Überfliegers des Garbagio, um zusätzliche optische Effekte für bestimmte Klassensetvorlagen der Befreiung von Lorenhall freizuschalten.\n\nDieser Effekt gilt für die gesamte Kriegsmeute." }
entries[236854] = { ["name"] = "Trank des mysteriösen Großbrands", ["text"] = "Nach dem Plündern: Chance, bei einem Angriff auf Euer Ziel dieses anzuzünden.\n\nHält 20 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht." }
entries[236856] = { ["name"] = "Trank des mysteriösen Systemschocks", ["text"] = "Nach dem Plündern: Chance, bei einem Angriff auf Euer Ziel diesem einen Schock zu verpassen. Geschockte Kreaturen erleiden einen regelmäßigen Betäubungseffekt.\n\nHält 20 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht." }
entries[236857] = { ["name"] = "Trank der mysteriösen Frostfessel", ["text"] = "Nach dem Plündern: Chance, bei einem Angriff auf Euer Ziel dessen Bewegungsgeschwindigkeit zu verringern.\n\nHält 20 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht." }
entries[236858] = { ["name"] = "Zo'kitafrucht", ["text"] = "Questgegenstand\n\"Wer einmal daran riecht, wird nie davon abbeißen.\"" }
entries[236859] = { ["name"] = "Ungebundene Tierhaut", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"Glänzt und schimmert, als würde sie sich gleich in Nichts auflösen.\"" }
entries[236870] = { ["name"] = "Trank der mysteriösen Bebensplitter", ["text"] = "Nach dem Plündern: Chance, bei einem Angriff auf Euer Ziel diesem durch Bewegung ausgelösten Flächenschaden zuzufügen.\n\nHält 20 Min. lang an und bleibt über den Tod hinaus bestehen.\n\nDieser Gegenstand wird sofort verbraucht." }
entries[236877] = { ["name"] = "Kristallisierte Essenz des Kaja'mits", ["text"] = "Wird beim Aufheben gebunden\n\"Gewährt eine Essenz des Kaja'mits, die beim Katalysator in Dornogal eingesetzt werden kann, um Rüstungen mit unglaublicher Macht zu durchwirken.\"\n<Zum Öffnen rechtsklicken>" }
entries[236881] = { ["name"] = "Leerenberührter Shiv", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Leerenberührt (1)\nEinhändig Dolch\n2,508 - 4,180 Schaden Geschwindigkeit 1.80\n(1,858 Schaden pro Sekunde)\n+1.634 Beweglichkeit\n+9.732 Ausdauer\nErhöht Eure kritische Trefferwertung um + 516.\n+ 422 Vielseitigkeit\nHaltbarkeit 80 / 80\nSchließt den Erfolg \"Symphonie der Masken (neuerlebt)\" ab, bei dem eine verstörende Vision abgeschlossen werden muss, während mindestens 5 Gesichtslosenmasken aktiv sind.\nErfordert den Erfolg \"Zunehmende Fortschritte\", bei dem 2 Ziele abgeschlossen und der Boss in einer der neuerlebten verstörenden Visionen besiegt werden muss.\nSchließt den Erfolg \"Maskierter Monolog (neuerlebt)\" ab, bei dem eine verstörende Vision abgeschlossen werden muss, während eine beliebige Gesichtslosenmaske aktiv ist.\nVerkaufspreis:" }
