entries[237009] = { ["name"] = "Zo'kita-Schutzausrüstung", ["text"] = "Questgegenstand\nBenutzen: Trägt Zo'kita-Ernteausrüstung, um Zo'kita sicher zu finden und zu ernten.\n\"Ein mit Pfeffer ausgekleideter Spezialfilter hält Gerüche von außen ab.\"" }
entries[237012] = { ["name"] = "Umfunktionierte azerothische Kamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\"" }
entries[237013] = { ["name"] = "Animasauger", ["text"] = "Questgegenstand\nBenutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\nKann beim Zaubern laufen. (3 Sek. Abklingzeit)\n\"Hat ein Portal auf der Rückseite der Waffe. Früher führte es nach K'aresh, aber wer weiß schon, wohin jetzt? Zumindest nicht hierher.\"" }
entries[237014] = { ["name"] = "Belobigung der Durchtrennten Fäden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 1500 Ruhm bei der von Euch gewählten Fraktion der Durchtrennten Fäden." }
entries[237019] = { ["name"] = "Verderbtes Harz", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"Von Leerenenergie erfülltes Pflanzenharz.\"" }
entries[237022] = { ["name"] = "Entsorgte Gegenstände", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"Davon könnte etwas essbar sein.\"" }
