entries[237259] = { ["name"] = "Kabummkanapee", ["text"] = "Einzigartig (2)\nBenutzen: Stellt im Verlauf von 20 Sek. ( 1125000 / 5 * 20) Gesundheit und ( 945060 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Kernwegoliven und Muschelpastete auf einem Buchweizenkräcker vom Hügelpinnenhof.\"\nVerkaufspreis:" }
entries[237260] = { ["name"] = "Glas mit Tageslichttau", ["text"] = "Einzigartig (2)\nBenutzen: Stellt im Verlauf von 20 Sek. ( 1125000 / 5 * 20) Gesundheit und ( 945060 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Ein mit Rosen angereichter Tau von Lorenhaller Deckenschimmel, der durch das künstliche Licht so gebrutzelt wurde, dass er technisch gesehen unbedenklich für die Gesundheit ist.\"\nVerkaufspreis:" }
entries[237266] = { ["name"] = "Gestohlene Schleierscherbe", ["text"] = "Questgegenstand\nEinzigartig (100)\n\"So wertvoll, dass allerlei Abschaum sie stehlen möchte.\"" }
entries[237267] = { ["name"] = "Ersatzweste der Ungekrönten", ["text"] = "Kosmetisch\nWird beim Aufheben gebunden\nBrust Leder\n2 Rüstung\nHaltbarkeit 80 / 80\nKlassen: Schurke\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[237268] = { ["name"] = "Wie man sich regelmäßig vor Strafzetteln drückt", ["text"] = "Einzigartig\n\"Ein abgenutzter Juristikfoliant. Enthält Weisheiten und Verfahren dazu, wie man sich in Lorenhall erfolgreich vor Strafzetteln drückt.\"\nVerkaufspreis:" }
entries[237276] = { ["name"] = "Runderneuerter Raketengleiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Schießt Euch in die Luft und gleitet sanft zu Boden. Kann nur im Freien in Lorenhall verwendet werden. (3 Min Abklingzeit)\n\"Das Etikett mit dem Warnhinweis ist angebrannt und lässt sich nicht lesen.\"\nVerkaufspreis:" }
entries[237305] = { ["name"] = "Kalkiger Shungit", ["text"] = "\"Ich verstehe es nicht. Es ist nur ein Haufen Steine.\"\nVerkaufspreis:" }
entries[237306] = { ["name"] = "NEUES goblinisches heißes Eisen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versucht, das NEUE goblinische heiße Eisen einem verbündeten Spielercharakter zuzuwerfen. Falls er Platz in seinem Rucksack hat, wird er es fangen... vorausgesetzt, Ihr könnt es sicher werfen! (2 Sek. Abklingzeit)\n\"Brandneues Gefühl, gleiche alte Gefahr!\"\nVerkaufspreis:" }
entries[237313] = { ["name"] = "Definitiv legitimes Samophlang", ["text"] = "\"110% authentisches Samophlang aus Lorenhall, das auf keinen Fall aus einem Müllhaufen gefischt wurde. Der Rauch und die Funken sind ganz normal!\"\nVerkaufspreis:" }
